<?php require_once 'config.php';require_login();if(($_SESSION['user']['role']??'')!=='student'){flash('Apenas contas de estudante podem submeter candidaturas.','error');header('Location: bolsas.php');exit;}if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: bolsas.php');exit;}verify_csrf();$sid=(int)($_POST['scholarship_id']??0);$mot=trim($_POST['motivation']??'');$st=db()->prepare("SELECT id FROM bolsa WHERE id=? AND status='published' AND (deadline IS NULL OR deadline>=CURDATE())");$st->execute([$sid]);if(!$st->fetch()){flash('Esta bolsa não está disponível para candidatura.','error');header('Location: bolsas.php');exit;}try{$st=db()->prepare('INSERT INTO candidatura(user_id,scholarship_id,motivation) VALUES(?,?,?)');$st->execute([$_SESSION['user']['id'],$sid,$mot?:null]);flash('Candidatura submetida. Podes acompanhar o estado no teu painel.');}catch(PDOException $e){flash($e->getCode()==='23000'?'Já te candidataste a esta bolsa.':'Não foi possível submeter a candidatura.','error');}header('Location: painel.php');exit;
